def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    max_prev_bid = 0.0
    urgent_opp = False

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp = True
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > max_prev_bid:
                    max_prev_bid = float(bid)

    if not alive:
        return min(budget, 18.0)

    total_players = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < total_players
    very_tight = expected_units < max(1.6, total_players - 1)

    if prev_bids:
        sorted_bids = sorted(prev_bids, reverse=True)
        top1 = sorted_bids[int(0)]
        top2 = sorted_bids[int(1)] if len(sorted_bids) > 1 else top1
    else:
        top1 = 55.0
        top2 = 45.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(88.0, top1 + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity:
            bid = max(76.0, top1 + 2.0)
        else:
            bid = max(58.0, top2 + 1.5)
    else:
        if very_tight:
            bid = max(72.0, min(top1 + 1.5, 86.0))
        elif scarcity:
            if top1 >= 80.0 and hp >= 6:
                bid = 61.0
            else:
                bid = max(59.0, min(top2 + 2.0, 74.0))
        else:
            if top1 >= 80.0:
                bid = 34.0
            elif top1 >= 60.0:
                bid = 46.0
            else:
                bid = max(32.0, top2 * 0.78)

    if urgent_opp and scarcity and hp >= 5:
        bid = max(bid, min(top1 + 2.5, 84.0))

    if day >= 8 and hp >= 6 and no_water_days == 0 and not very_tight:
        bid *= 0.9

    min_safe = 8.0 if hp >= 6 else 18.0
    bid = max(min_safe, bid)
    bid = min(budget, bid)
    if budget <= 0:
        return 0.0
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate pressure signal
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids)
        second_prev_bid = sorted_b[-2]

    # Estimate how many water units are likely needed/available
    # (Use supply to gauge competition intensity.)
    # If supply is tight, bid more.
    supply_tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_tightness = max(0.0, min(1.0, supply_tightness))

    # Base bid target: aim to beat the top yesterday bidder when they were aggressive.
    # If their highest bid was high, we must respond.
    response_level = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        response_level = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        response_level = 0.7
    elif highest_prev_bid > 0.0:
        response_level = 0.4
    else:
        response_level = 0.2

    # If I'm in danger (low hp or accumulating dry days), increase bid.
    danger = 0.0
    if hp <= 2:
        danger = 1.0
    elif hp <= 4:
        danger = 0.7
    elif hp <= 6:
        danger = 0.4
    else:
        danger = 0.2

    # If no_water_days is already high, bid more.
    if no_water_days >= 3:
        danger = max(danger, 0.9)
    elif no_water_days >= 2:
        danger = max(danger, 0.7)

    # Compute target bid.
    # Beat the highest yesterday bidder by a small increment, but cap.
    increment = 2.5 + 2.0 * supply_tightness
    target = 0.0

    if highest_prev_bid > 0.0:
        target = highest_prev_bid + increment * (0.6 + 0.4 * response_level)
    else:
        target = DAILY_SALARY * (0.5 + 0.3 * supply_tightness)

    # Adjust for danger.
    target *= (0.85 + 0.3 * danger)

    # Keep bids in a reasonable band for this meta-round.
    # Also ensure we can afford it.
    min_bid = 0.0
    max_bid_cap = DAILY_SALARY * (0.95 if danger > 0.8 else 0.75)
    target = max(min_bid, min(target, max_bid_cap))

    # If supply is very tight, push closer to cap.
    if supply_tightness > 0.7:
        target = min(max_bid_cap, target + 0.15 * DAILY_SALARY)

    # Final affordability clamp.
    bid = min(budget, target)

    # If budget is too low, still try to secure some water.
    if bid < DAILY_SALARY * 0.15 and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.2)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

