    else:
        if day <= 3:
            base_bid = min(budget, DAILY_SALARY * 0.4)
        elif day >= 8:
            base_bid = min(budget, DAILY_SALARY * 0.7)
        else:
            base_bid = min(budget, DAILY_SALARY * 0.5)

    if max_prev > base_bid:
        target = max_prev + 1.5
        if target > budget:
            target = budget
        if scarcity > 0.6 and hp <= 3:
            target = max(target, DAILY_SALARY * 0.85)
        base_bid = target
    elif scarcity > 0.7 and hp <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

