def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    HIGH_BID_THRESHOLD = DAILY_SALARY * 0.85
    LOW_HP_AGGRESSIVE_BID = DAILY_SALARY * 0.95
    HIGH_HP_CONSERVATIVE_BID = DAILY_SALARY * 0.3
    DEFAULT_ADAPTIVE_BID = DAILY_SALARY * 0.5
    FALLBACK_LOW_HP_BID = DAILY_SALARY * 0.9
    FALLBACK_NORMAL_HP_BID = DAILY_SALARY * 0.55

    current_bid = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= HIGH_BID_THRESHOLD:
            if my_status['hp'] > 3:
                current_bid = HIGH_HP_CONSERVATIVE_BID
            else:
                current_bid = LOW_HP_AGGRESSIVE_BID
        else:
            current_bid = max(DEFAULT_ADAPTIVE_BID, highest_prev_bid + 1.5)
    else:
        if my_status['hp'] <= 2:
            current_bid = FALLBACK_LOW_HP_BID
        else:
            current_bid = FALLBACK_NORMAL_HP_BID

    final_bid = min(my_status['budget'], current_bid)

    if final_bid <= 0.0 and my_status['budget'] > 0:
        final_bid = 1.0

    return final_bid
